policy.hostRules:
firecracker_pid=817907 netns=ns-3 host_veth=e2b-3
-A PREROUTING -d 192.0.2.1/32 -i e2b-3 -p tcp -m tcp --dport 80 -j REDIRECT --to-ports 5010
-A PREROUTING -d 192.0.2.1/32 -i e2b-3 -p tcp -m tcp --dport 111 -j REDIRECT --to-ports 5012
-A PREROUTING -d 192.0.2.1/32 -i e2b-3 -p tcp -m tcp --dport 2049 -j REDIRECT --to-ports 5011
-A PREROUTING -i e2b-3 -p tcp -m tcp --dport 80 -j REDIRECT --to-ports 5016
-A PREROUTING -i e2b-3 -p tcp -m tcp --dport 443 -j REDIRECT --to-ports 5017
-A PREROUTING -i e2b-3 -p tcp -j REDIRECT --to-ports 5018
table inet slot-firewall {
	set filtered_always_denylist {
		type ipv4_addr
		flags interval
		counter
		elements = { 10.0.0.0/8 counter packets 0 bytes 0, 100.64.0.0/10 counter packets 0 bytes 0,
			     127.0.0.0/8 counter packets 0 bytes 0, 169.254.0.0/16 counter packets 0 bytes 0,
			     172.16.0.0/12 counter packets 0 bytes 0, 192.168.0.0/16 counter packets 0 bytes 0 }
	}
}
table inet slot-firewall {
	set filtered_denylist {
		type ipv4_addr
		flags interval
		counter
		elements = { 0.0.0.0/0 counter packets 2 bytes 152 }
	}
}
table inet slot-firewall {
	set filtered_allowlist {
		type ipv4_addr
		flags interval
		counter
		elements = { 1.1.1.1 counter packets 0 bytes 0 }
	}
}
table inet slot-firewall {
	chain PREROUTE_FILTER {
		type filter hook prerouting priority mangle; policy accept;
		iifname "tap0" ct state established,related meta l4proto != udp accept
		iifname "tap0" ct state established,related ct direction reply accept
		iifname "tap0" @nh,128,32 @filtered_always_allowlist accept
		iifname "tap0" @nh,128,32 @filtered_always_denylist drop
		iifname "tap0" meta l4proto != tcp @nh,128,32 @filtered_allowlist accept
		iifname "tap0" meta l4proto != tcp @nh,128,32 @filtered_denylist drop
	}
}
